        case .stop: true
        case .voice: false
        case .busy: true
        }
    }

    /// The glyph, or nil where the system draws the face (a spinner).
    var icon: JunoIcon? {
        switch self {
        case .send: .send
        case .stop: .stop
        case .voice: .audioLines
        case .busy: nil
        }
    }

    /// The face the web's composer shows for one of its states (`PRIMARY_FACES`).
    init?(composerState: String) {
        switch composerState {
        case "checking": self = .busy
        case "stop": self = .stop
        case "send": self = .send
        case "voice": self = .voice
        default: return nil
        }
    }
}

